$tab=isset($T[$_GET['tab']??''])?$_GET['tab']:'company';
if(is_post()){
  $a=$_POST['a']??'save';
  try{
  if($a==='save'){
    foreach($T[$tab][3] as $f){
      [$k,,$type]=$f+[2=>'text'];
      if($type==='file'){
        if(empty($_FILES[$k]['tmp_name'])||!is_uploaded_file($_FILES[$k]['tmp_name']))continue;
        $ext=strtolower(pathinfo($_FILES[$k]['name'],PATHINFO_EXTENSION));
        if(!in_array('.'.$ext,explode(',',$f[3]),true))throw new Exception('Invalid file type for '.$f[1]);
        if($k==='font_upload'){$n=preg_replace('/[^a-z0-9_-]+/i','-',pathinfo($_FILES[$k]['name'],PATHINFO_FILENAME));move_uploaded_file($_FILES[$k]['tmp_name'],STORAGE.'/fonts/'.$n.'.ttf');flash('Font "'.e($n).'" uploaded.');continue;}
        $dir=$k==='company_logo'?'assets/uploads':'storage/uploads';@mkdir(ROOT.'/'.$dir,0755,true);
        $dst=$dir.'/'.$k.'-'.token(4).'.'.$ext;
        move_uploaded_file($_FILES[$k]['tmp_name'],ROOT.'/'.$dst);
        Settings::set($k,$dst);continue;}
      if($type==='secret'){if(($_POST[$k]??'')!=='')Settings::set($k,trim($_POST[$k]));if(!empty($_POST['clear_'.$k]))Settings::set($k,'');continue;}
      if($type==='days'){Settings::set($k,implode(',',array_map('intval',$_POST[$k]??[])));continue;}
      if(array_key_exists($k,$_POST))Settings::set($k,trim($_POST[$k]));}
    if($tab==='pricing'&&!empty($_POST['currency'])&&isset($cur[$_POST['currency']])&&($_POST['currency_symbol']??'')==='')Settings::set('currency_symbol',$cur[$_POST['currency']]);
    if($tab==='pricing'&&!empty($_POST['remove_proposal']))Settings::set('proposal_pdf','');
    if($tab==='whatsapp'&&setting('wa_api_headers')&&json_decode(setting('wa_api_headers'))===null)flash('Custom headers are not valid JSON.','err');
    flash('Settings saved.');}
  if($a==='test_email'){Mailer::send(user()['email'],'Setu test email','<p>Your SMTP settings work.</p>','Your SMTP settings work.');flash('Test email sent to '.e(user()['email']).'.');}
  if($a==='test_imap'){$s=Mailer::inboxSenders(3);flash('IMAP connected. '.count($s).' sender(s) in the last 3 days.');}
  if($a==='test_wa'){$to=trim($_POST['to']??'');$id=WhatsApp::send($to,'Test message from Setu ✅',[],['business_name'=>'Test','sender_name'=>setting('sender_name')]);flash($id==='manual'?'Manual mode: <a href="'.e(WhatsApp::link($to,'Test message from Setu')).'" target="_blank">open WhatsApp</a>':'WhatsApp test sent ('.e($id).').');}
  if($a==='test_voice'){$to=trim($_POST['to']??'');if($to==='')throw new Exception('Enter a phone number.');$lid=CRM::create(['contact_name'=>'Test call','name'=>'Setu test','phone'=>$to],'manual','Voice test');Voice::start($lid,[]);flash('Test call started – it appears in the "Setu test" lead journey.');}
  if($a==='test_maps'){$city=trim($_POST['city']??'')?:'Pune';if(setting('maps_source','places')==='places'){$d=Maps::diagnose($city);flash(implode('<br>',array_map('e',$d)),strpos(end($d),'✓')===0?'ok':'err');}else{$r=Maps::search('cafe in '.$city,null,'serpapi');flash('SerpAPI works – got '.count($r['items']).' listings, e.g. '.e($r['items'][0]['name']??'—').'.');}}
  if($a==='src_add'){$ty=isset(Capture::types()[$_POST['type']??''])?$_POST['type']:'webhook';$cfg=$ty==='facebook'?['verify_token'=>token(8)]:($ty==='google'?['google_key'=>token(10)]:[]);DB::insert('sources',['type'=>$ty,'name'=>mb_substr(trim($_POST['name']??'')?:Capture::types()[$ty][0],0,110),'token'=>token(16),'config'=>je($cfg)]);flash('Lead source created – copy its URL below.');}
  if($a==='src_save'){$s=DB::row('SELECT * FROM sources WHERE id=?',[(int)$_POST['id']]);if($s){$cfg=jd($s['config']);foreach(($_POST['cfg']??[]) as $k=>$v)if(!($k==='page_token'||$k==='app_secret')||$v!=='')$cfg[$k]=trim($v);DB::update('sources',['name'=>mb_substr(trim($_POST['name']??$s['name']),0,110),'active'=>empty($_POST['active'])?0:1,'config'=>je($cfg)],'id=?',[$s['id']]);flash('Saved.');}}
  if($a==='src_del'){DB::q('DELETE FROM sources WHERE id=?',[(int)$_POST['id']]);flash('Lead source deleted.');}
  if($a==='src_test'){$s=DB::row('SELECT * FROM sources WHERE id=?',[(int)$_POST['id']]);if($s){$sample=$s['type']==='google'?['google_key'=>jd($s['config'])['google_key']??'','is_test'=>true,'campaign_id'=>'123','user_column_data'=>[['column_id'=>'FULL_NAME','column_name'=>'Full Name','string_value'=>'Test Lead (Google)'],['column_id'=>'PHONE_NUMBER','column_name'=>'Phone','string_value'=>'+919800000000'],['column_id'=>'EMAIL','column_name'=>'Email','string_value'=>'test.google@example.com']]]:['name'=>'Test Lead','phone'=>'+919800000001','email'=>'test@example.com','company'=>'Test Company','message'=>'This is a test enquiry from Setu settings.'];
    $r=http(Capture::url($s),['json'=>$sample,'timeout'=>20]);flash('Test sent – HTTP '.$r['code'].'. '.($r['code']===200?'Check the Leads list.':'Response: '.e(substr($r['body'],0,200))),$r['code']===200?'ok':'err');}}
  if($a==='field_add'){$label=trim($_POST['label']??'');if($label==='')throw new Exception('Enter a field name.');$key=trim(preg_replace('/[^a-z0-9]+/','_',strtolower($_POST['fkey']??'')?:strtolower($label)),'_');if(in_array($key,CRM::CORE,true)||DB::val('SELECT id FROM fields WHERE fkey=?',[$key]))throw new Exception('A field with key "'.$key.'" already exists.');DB::insert('fields',['fkey'=>$key,'label'=>mb_substr($label,0,110),'type'=>$_POST['type']??'text','options'=>trim($_POST['options']??''),'required'=>empty($_POST['required'])?0:1,'sort'=>(int)DB::val('SELECT COALESCE(MAX(sort),0)+1 FROM fields')]);flash('Field added.');}
  if($a==='field_save'){foreach(($_POST['f']??[]) as $id=>$f)DB::update('fields',['label'=>mb_substr(trim($f['label']),0,110),'type'=>$f['type'],'options'=>trim($f['options']??''),'required'=>empty($f['required'])?0:1,'sort'=>(int)$f['sort']],'id=?',[(int)$id]);flash('Fields saved.');}
  if($a==='field_del'){DB::q('DELETE FROM fields WHERE id=?',[(int)$_POST['fid']]);flash('Field deleted (existing values stay in the lead data).');}
  if($a==='password'){
    $u=DB::row('SELECT * FROM users WHERE id=?',[user()['id']]);
    if(!password_verify($_POST['old']??'',$u['password']))throw new Exception('Current password is wrong.');
    $up=['name'=>trim($_POST['name']??$u['name']),'email'=>trim($_POST['email']??$u['email'])];
    if(($_POST['new']??'')!==''){if(strlen($_POST['new'])<8)throw new Exception('New password must be at least 8 characters.');$up['password']=password_hash($_POST['new'],PASSWORD_DEFAULT);}
    DB::update('users',$up,'id=?',[$u['id']]);flash('Account updated.');}
  if($a==='adduser'){if(strlen($_POST['pw']??'')<8)throw new Exception('Password must be at least 8 characters.');DB::insert('users',['name'=>trim($_POST['name']),'email'=>trim($_POST['email']),'password'=>password_hash($_POST['pw'],PASSWORD_DEFAULT)]);flash('User added.');}
  if($a==='deluser'&&(int)$_POST['id']!==(int)user()['id']){DB::q('DELETE FROM users WHERE id=?',[(int)$_POST['id']]);flash('User removed.');}
  }catch(Throwable $e){flash(e($e->getMessage()),'err');}
  redirect(url('settings',['tab'=>$tab]));}
